        need("R81_DERIVED_BOUND_INPUT_1".equals(str(proof,"revision"))&&child.ast.canonical.equals(str(proof,"childAst"))&&child.ast.structuralHash.equals(str(proof,"childAstHash"))&&child.manifest.hash.equals(str(proof,"childManifestHash")),"BOUND_DERIVED_CHILD_IDENTITY");
